      { name:"间距-常规", value:"16px · --dd-space-4", semantic:"DaiDai 普通组件的默认节奏。", use:"普通卡片内边距、表单组、左右分栏内留白。", avoid:"不用于高密度数据表格。", preview:<span className="h-1 w-8 bg-foreground"/> },
      { name:"间距-大", value:"24px · --dd-space-6", semantic:"明确分割两个独立信息区。", use:"面板区块、Dialog 分段、页面次级模块。", avoid:"不用于按钮、输入框等控件内部。", preview:<span className="h-1 w-12 bg-foreground"/> },
      { name:"间距-模块", value:"32px · --dd-space-8", semantic:"页面级模块之间的留白。", use:"页面主 Section、工作区主要内容块。", avoid:"不用于卡片内部与密集工具区。", preview:<span className="h-1 w-16 bg-foreground"/> }
