      { name:"动效-快速", value:"120ms · --dd-duration-fast", semantic:"手指或鼠标操作的微反馈。", use:"Hover、Pressed、Checkbox、Toggle。", avoid:"不用于浮层和内容进入。", preview:<span className="h-1 w-4 bg-foreground"/> },
      { name:"动效-标准", value:"180ms · --dd-duration-standard", semantic:"DaiDai 默认的状态过渡节奏。", use:"菜单、Popover、Toast、选中状态。", avoid:"不要在同一元素重复叠加。", preview:<span className="h-1 w-8 bg-foreground"/> },
      { name:"动效-布局", value:"220ms · --dd-duration-layout", semantic:"空间重排时保持理解连续性。", use:"侧栏、折叠、分屏、容器展开。", avoid:"不用于普通按钮 Hover。", preview:<span className="h-1 w-11 bg-foreground"/> },
      { name:"动效-强调", value:"280ms · --dd-duration-expressive", semantic:"低频结果需要被用户感知。", use:"完成、发布、成就与重要成功反馈。", avoid:"不可用于列表每条数据刷新。", preview:<span className="h-1 w-14 bg-foreground"/> }
